// Records where every shipping picture comes from, inside the picture where the format allows it: a PNG gets a
// text chunk (keyword impeccable:prompt), a WebP gets a JSON file beside it ({ "prompt": ... }). Nothing here is
// generated by an image model; every picture is drawn from the project's own sources or sourced with its licence.
// usage: node tools/marketing/provenance.mjs
// Run it after the pictures are made (capture, site-images, loop, og, store-shots, trailer, render-icons).
import { readFileSync, writeFileSync, readdirSync, existsSync, statSync } from 'node:fs';
import { join, basename } from 'node:path';

const KEY = 'impeccable:prompt';

const CRC = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; }
  return (buf) => { let c = 0xffffffff; for (const b of buf) c = t[(c ^ b) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
})();

/** Writes (or replaces) the provenance text chunk of a PNG, just before IEND. */
function pngText(file, text) {
  const data = readFileSync(file);
  const chunks = [];
  let at = 8;
  while (at < data.length) {
    const len = data.readUInt32BE(at);
    const type = data.toString('latin1', at + 4, at + 8);
    const end = at + 12 + len;
    const body = data.subarray(at + 8, at + 8 + len);
    const ours = type === 'tEXt' && body.subarray(0, KEY.length + 1).equals(Buffer.from(`${KEY}\0`, 'latin1'));
    if (!ours) chunks.push({ type, raw: data.subarray(at, end) });
    at = end;
  }
  const payload = Buffer.concat([Buffer.from(`${KEY}\0`, 'latin1'), Buffer.from(text, 'latin1')]);
  const head = Buffer.alloc(8);
  head.writeUInt32BE(payload.length, 0);
  head.write('tEXt', 4, 'latin1');
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(CRC(Buffer.concat([Buffer.from('tEXt', 'latin1'), payload])), 0);
  const chunk = Buffer.concat([head, payload, crc]);
  const parts = [data.subarray(0, 8)];
  for (const c of chunks) { if (c.type === 'IEND') parts.push(chunk); parts.push(c.raw); }
  writeFileSync(file, Buffer.concat(parts));
}

function record(file, origin) {
  const text = `Origin: ${origin}`;
  // A PNG text chunk holds Latin-1 only; the JSON beside a WebP keeps the text whole.
  if (file.endsWith('.png')) pngText(file, text.normalize('NFKD').replace(/[^\x20-\x7e]/g, ''));
  else writeFileSync(`${file}.json`, `${JSON.stringify({ prompt: text }, null, 2)}\n`);
}

const list = (dir, test) => (existsSync(dir) ? readdirSync(dir).filter((f) => statSync(join(dir, f)).isFile() && test(f)).map((f) => join(dir, f)) : []);
const walk = (dir, test) => (existsSync(dir) ? readdirSync(dir).flatMap((f) => { const p = join(dir, f); return statSync(p).isDirectory() ? walk(p, test) : test(f) ? [p] : []; }) : []);
const raster = (f) => /\.(png|webp)$/.test(f);

const ICON = 'drawn for this project in art/icon.svg and rendered by tools/render-icons.mjs and @capacitor/assets.';
let count = 0;
const mark = (files, origin) => { for (const f of files) { record(f, typeof origin === 'function' ? origin(f) : origin); count++; } };

mark(list('assets', raster), ICON);
mark(list('app/public/img', raster), ICON);
mark(list('store/graphics', (f) => f.startsWith('icon')), ICON);

const credits = existsSync('site/img/world/credits.json') ? JSON.parse(readFileSync('site/img/world/credits.json', 'utf8')) : [];
mark(list('site/img/world', raster), (f) => {
  const c = credits.find((x) => x.file === basename(f));
  return c ? `${c.title}, by ${c.creator}, ${c.licence}, from Wikimedia Commons (${c.page}). Changes: ${c.changes}.` : 'sourced photograph, see site/img/world/credits.json.';
});
for (const lang of ['en', 'ar']) {
  mark(list(`site/img/${lang}`, raster), (f) => (basename(f).startsWith('swipe-loop')
    ? 'first frame of the swipe loop drawn by tools/marketing/loop.mjs from the game itself (capture build).'
    : basename(f).startsWith('stage-')
      ? 'an element of the game itself, cut out at its own size by tools/marketing/capture.mjs from the capture build and resized by tools/marketing/site-images.py.'
      : 'a screen of the game itself, captured by tools/marketing/capture.mjs from the capture build and resized by tools/marketing/site-images.py.'));
}
mark(list('site/img', (f) => /^og-.*\.png$/.test(f)), 'link preview drawn by tools/marketing/og.mjs around the game\'s own debrief screen, in the website\'s colours and type.');
mark(walk('store/screenshots', raster), 'store screenshot drawn by tools/marketing/store-shots.mjs around a screen of the game captured by tools/marketing/capture.mjs.');
mark(list('store/graphics', (f) => f.startsWith('feature-graphic')), 'feature graphic drawn by tools/marketing/store-shots.mjs around the game\'s own debrief screen.');
mark(list('store/trailer', raster), 'a frame of the trailer built by tools/marketing/trailer.mjs from game footage recorded by tools/marketing/record.mjs.');
console.log(`provenance recorded for ${count} pictures`);
